elseif($action==='role_assign'){SaaSRoles::assign($project,$_POST['username']??'',$_POST['role_id']??'');$message='نقش عضو ثبت شد.';}
else throw new RuntimeException('عملیات معتبر نیست.');$account=SaaSAccounts::projectAccount($pid);}}
catch(Throwable $e){http_response_code(422);$error=$e instanceof RuntimeException?$e->getMessage():'عملیات انجام نشد.';}
